// One Adzuna query per search term x location (local radius + remote keyword).
const c = $input.first().json;
const base = {
  max_days_old: c.max_days_old,
  results_per_page: c.results_per_page,
  sort_by: 'date',
  category: c.adzuna_category,
  'content-type': 'application/json',
};

const items = [];
for (const term of c.adzuna_terms) {
  items.push({ json: {
    search_term: term,
    search_type: 'local',
    query: { ...base, what: term, where: c.local_area, distance: c.distance_km },
  }});
  items.push({ json: {
    search_term: term,
    search_type: 'remote',
    query: { ...base, what: `${term} remote` },
  }});
}
return items;

// Normalise Adzuna results into the shared job shape used by every source.
const clean = (s) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&hellip;/g, '…').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—').replace(/&pound;/g, '£')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/\s+/g, ' ')
  .trim();

const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const formatSalary = (r) => {
  const { salary_min: min, salary_max: max } = r;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return String(r.salary_is_predicted) === '1' ? `${range} (est.)` : range;
};

const must = $('Search config').first().json.title_must_contain ?? {};
const titleOk = (i, title) => {
  let term = '';
  try { term = $('Build search queries').itemMatching(i).json.search_term ?? ''; } catch (e) { return true; }
  const word = must[term.toLowerCase()];
  return !word || String(title ?? '').toLowerCase().includes(word);
};

const out = [];
for (const [i, item] of $input.all().entries()) {
  for (const r of item.json.results ?? []) {
    if (!titleOk(i, r.title)) continue;
    out.push({ json: {
      job_id: `adzuna_${r.id}`,
      source: 'adzuna',
      title: clean(r.title),
      company: clean(r.company?.display_name),
      location: clean(r.location?.display_name),
      salary: formatSalary(r),
      url: r.redirect_url ?? '',
      description: clean(r.description),
      posted: r.created ?? '',
      point: r.latitude != null && r.longitude != null ? { lat: Number(r.latitude), lon: Number(r.longitude) } : null,
    }});
  }
}
return out;

// Keep only jobs not already in the sheet: same job_id, or same title + company
// (catches the same job listed on both Adzuna and Reed on different days).
const dedupKey = j => `${j.title ?? ''}|${j.company ?? ''}`
  .toLowerCase().replace(/[^a-z0-9|]+/g, ' ').replace(/\s+/g, ' ').trim();
const rows = $('Read existing jobs').all().map(i => i.json);
const seenIds = new Set(rows.map(r => String(r.job_id ?? '').trim()).filter(Boolean));
const seenKeys = new Set(rows.filter(r => r.title).map(dedupKey));
return $('Remove duplicates in run').all()
  .filter(i => !seenIds.has(i.json.job_id) && !seenKeys.has(i.json.dedup_key));

// Drop roles that are clearly too senior or the wrong field before spending LLM tokens on them.
// Whole words only, so "java" drops "Java Developer" but not "JavaScript Developer".
// keep_title_phrases are ignored by the check ("Implementation Manager" survives "manager").
const c = $('Search config').first().json;
const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const wordsRe = (list, flags) => list?.length ? new RegExp('\\b(' + list.map(escape).join('|') + ')\\b', flags) : null;
const drop = wordsRe(c.exclude_title_patterns, 'i'), keep = wordsRe(c.keep_title_phrases, 'gi');
return $input.all().filter(i => {
  const title = String(i.json.title ?? '');
  return !drop?.test(keep ? title.replace(keep, ' ') : title);
});

// Rank by title match and location, then score at most max_jobs_per_run jobs.
// Jobs left out are not logged, so they are considered again tomorrow while still recent.
// ===== Location helpers (same code wherever a job's location is judged) =====
const geoKey = loc => String(loc ?? '').split(/[,(]/)[0].trim();
// "GU212JX" or "GL50" -> outcode; anything else is a place name.
const outcodeOf = s => {
  const t = s.toUpperCase().replace(/\s+/g, '');
  return /^([A-Z]{1,2}\d[A-Z\d]?)(\d[A-Z]{2})$/.exec(t)?.[1] ?? (/^[A-Z]{1,2}\d[A-Z\d]?$/.test(t) ? t : null);
};
const geoUrl = key => outcodeOf(key)
  ? 'https://api.postcodes.io/outcodes/' + outcodeOf(key)
  : 'https://api.postcodes.io/places?limit=5&q=' + encodeURIComponent(key);
const geoPoint = resp => {
  const r = resp?.result;
  const p = Array.isArray(r) ? ['City', 'Town', 'Suburban Area', 'Village'].map(t => r.find(x => x.local_type === t)).find(Boolean) : r;
  return p && p.latitude != null ? { lat: Number(p.latitude), lon: Number(p.longitude) } : null;
};
// Straight-line miles.
const milesBetween = (a, b) => {
  const rad = x => x * Math.PI / 180;
  const h = Math.sin(rad(b.lat - a.lat) / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(rad(b.lon - a.lon) / 2) ** 2;
  return Math.round(2 * 3958.8 * Math.asin(Math.sqrt(h)));
};
const isCountry = key => /^(|uk|united kingdom|england|scotland|wales|great britain|remote|nationwide|home.?based)$/i.test(key);
// remote / remote offered / hybrid / on-site / unclear, from the words of the listing.
const workMode = job => {
  const head = `${job.title ?? ''} | ${job.location ?? ''}`, text = `${head} | ${job.description ?? ''}`;
  const strong = /\b(fully|100%|completely|entirely|permanently)[ -]remote\b|\bremote[ -](first|only|based)\b|\bbased remotely\b|\bremote \(?(uk|within the uk)\b|\b(location|working|work pattern)\s*[:-]?\s*(predominantly |mostly |mainly )?remote\b|\b(predominantly|mostly|mainly) remote\b/i;
  const start = String(job.description ?? '').slice(0, 200), offered = /\/ ?remote working\b|\bremote (working|work) (is )?(available|possible|offered|considered)\b/i;
  if (/\bremote\b/i.test(head) && !/\b(no|not) remote\b/i.test(head) && !/hybrid/i.test(head)) return 'remote';
  if (/\(remote\b[^)]*\)/i.test(start)) return 'remote';
  if (strong.test(text) && !/\b(no|not) (fully|100%|completely) remote\b/i.test(text)) return 'remote';
  if (/\bhybrid\b(?![ -]?(cloud|infrastructure|environment|mobile|app|azure|identity|network|model of))/i.test(text) || /\b(one|two|three|four|[1-4])(\s*(-|to|–)\s*[1-5])? days?( a| per| each)?( week)? ?(in|at|on|from)[ -](the |our )?(office|site|home)/i.test(text)) return 'hybrid';
  if (offered.test(text)) return 'remote offered';
  if (/\b(on[- ]?site|office[- ]based|in[- ]office|in[- ]person)\b/i.test(text) && !/\bremote\b/i.test(text)) return 'on-site';
  return 'unclear';
};
const locationVerdict = (mode, miles, c) => {
  const hy = c.hybrid_miles, on = c.onsite_miles;
  if (mode === 'remote') return 'ok';
  if (mode === 'remote offered') return miles != null && miles <= on ? 'ok' : 'possible';
  if (miles == null) return 'unknown';
  if (miles > hy) return mode === 'unclear' ? 'probably too far' : 'too far';
  if (mode === 'hybrid' || miles <= on) return 'ok';
  return mode === 'on-site' ? 'too far' : 'possible';
};
// The place lookup covers Great Britain only.
const NI = { lat: 54.6, lon: -5.93 };
const locate = (job, point, c) => {
  if (!point && /northern ireland|\bbelfast\b|\bcounty antrim\b/i.test(job.location ?? '')) point = NI;
  const miles = point ? milesBetween(c.home, point) : null, mode = workMode(job);
  return { work_mode: mode, miles, location_verdict: locationVerdict(mode, miles, c) };
};
// ===== End of location helpers =====
const c = $('Search config').first().json;
const points = new Map();
$('Look up places').all().forEach((it, i) => { const key = $('Places to look up').all()[i]?.json?.key; if (key) points.set(key, geoPoint(it.json)); });
const CORE = /typescript|\breact\b|node\.?js|\.net\b|c#|c sharp|full[ -]?stack/i;
const SECOND = /\b(software|web|application|applications|api|integration|integrations|automation|front[ -]?end|back[ -]?end|mobile)\b.*\b(developer|engineer|programmer)\b|\bdeveloper\b|implementation|n8n/i;
const rank = j => {
  const t = j.title ?? '';
  return (CORE.test(t) ? 40 : SECOND.test(t) ? 20 : 0)
    + (/\b(junior|graduate|mid)\b/i.test(t) ? 10 : 0)
    + (/\b(senior|snr|sr|staff)\b/i.test(t) ? -20 : 0)
    + ({ ok: 30, possible: 15, unknown: 0, 'probably too far': -15, 'too far': -40 }[j.location_verdict] ?? 0);
};
return $('Drop obvious mismatches').all()
  .map(i => { const j = i.json, point = j.point ?? points.get(geoKey(j.location)) ?? null; return { ...j, point, ...locate(j, point, c) }; })
  .map(j => ({ ...j, rank: rank(j) }))
  .sort((a, b) => b.rank - a.rank || String(b.posted).localeCompare(String(a.posted)))
  .slice(0, c.max_jobs_per_run ?? 40)
  .map(json => ({ json }));

// Parse and validate each Claude response. One bad response never breaks the run:
// it falls back to score = null with the reason recorded.
const jobs = $('Build Claude request').all();

const fallback = (why) => ({
  score: null, matched_skills: [], missing_skills: [],
  seniority_fit: 'unclear', remote_or_local_ok: null, reason: `parse error: ${why}`,
});

const parse = (resp) => {
  if (!resp || resp.error) {
    const e = resp?.error;
    return fallback(typeof e === 'string' ? e : (e?.message ?? 'request failed'));
  }
  if (resp.stop_reason === 'refusal') return fallback('model refused');
  if (resp.stop_reason === 'max_tokens') return fallback('response cut off');
  const text = (resp.content ?? []).find(b => b.type === 'text')?.text;
  if (!text) return fallback('no text in response');
  let data;
  try {
    data = JSON.parse(text.replace(/^\s*```(?:json)?\s*|\s*```\s*$/g, ''));
  } catch (e) {
    return fallback('invalid JSON');
  }
  if (!Number.isInteger(data.score) || data.score < 0 || data.score > 100) {
    return fallback('score not an integer 0-100');
  }
  const list = (a) => (Array.isArray(a) ? a.map(String).slice(0, 6) : []);
  return {
    score: data.score,
    matched_skills: list(data.matched_skills),
    missing_skills: list(data.missing_skills),
    seniority_fit: data.seniority_fit ?? 'unclear',
    remote_or_local_ok: typeof data.remote_or_local_ok === 'boolean' ? data.remote_or_local_ok : null,
    reason: String(data.reason ?? '').trim(),
  };
};

return $input.all().map((item, idx) => {
  const { claude_request, ...job } = jobs[idx]?.json ?? {};
  const resp = item.json;
  // Location caps are enforced here: the model may say "capped" and still score higher.
  const parsed = parse(resp), cap = { 'probably too far': 45, 'too far': 35 }[job.location_verdict];
  if (cap != null && parsed.score > cap) parsed.score = cap;
  if (job.location_verdict) parsed.remote_or_local_ok = ['ok', 'possible'].includes(job.location_verdict);
  return { json: {
    ...job,
    ...parsed,
    input_tokens: resp?.usage?.input_tokens ?? 0,
    output_tokens: resp?.usage?.output_tokens ?? 0,
  }};
});

// Build the daily HTML digest: top 5 new jobs scoring >= 60, plus run stats.
const jobs = $('Parse score').all().map(i => i.json);
const MIN_SCORE = 60, TOP_N = 5;
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const top = jobs
  .filter(j => Number.isInteger(j.score) && j.score >= MIN_SCORE)
  .sort((a, b) => b.score - a.score)
  .slice(0, TOP_N);

const scored = jobs.filter(j => Number.isInteger(j.score)).length;
const failed = jobs.length - scored;
const inTok = jobs.reduce((s, j) => s + (j.input_tokens || 0), 0);
const outTok = jobs.reduce((s, j) => s + (j.output_tokens || 0), 0);
// claude-haiku-5-5: $0.10 per 1M input tokens, $0.50 per 1M output tokens.
const costUsd = (inTok * 0.10 + outTok * 0.50) / 1e6;
const cvRuns = (() => { try { return $('Generate CVs').all().map(i => i.json).filter(r => r.job_id); } catch (e) { return []; } })();
const cvById = Object.fromEntries(cvRuns.map(r => [r.job_id, r]));
const cvOk = cvRuns.filter(r => r.cv_ok), cvFailed = cvRuns.length - cvOk.length;
const cvOlder = cvOk.filter(r => !jobs.some(j => j.job_id === r.job_id)).length;
const cvCost = cvRuns.reduce((s, r) => s + (r.cv_cost_usd || 0), 0);
const cvIn = cvRuns.reduce((s, r) => s + (r.cv_input_tokens || 0), 0), cvOut = cvRuns.reduce((s, r) => s + (r.cv_output_tokens || 0), 0);
const briefRuns = (() => { try { return $('Generate briefs').all().map(i => i.json).filter(r => r.job_id); } catch (e) { return []; } })();
const briefById = Object.fromEntries(briefRuns.map(r => [r.job_id, r]));
const briefOk = briefRuns.filter(r => r.brief_ok).length, briefFailed = briefRuns.length - briefOk;
const briefCost = briefRuns.reduce((s, r) => s + (r.brief_cost_usd || 0), 0);
const link = (url, label) => /^https:\/\//i.test(url ?? '') ? ` &middot; <a href="${esc(url)}">${label}</a>` : '';
const cvLink = j => link(cvById[j.job_id]?.cv_link, 'Tailored CV') + link(briefById[j.job_id]?.job_brief_link, 'Job brief');
const day = $now.setZone('Europe/London').toFormat('ccc d LLL');

const card = j => `
  <tr><td style="padding:12px 0;border-bottom:1px solid #e5e5e5">
    <div style="font-size:16px"><b>${j.score}</b> &middot; ${/^https?:\/\//i.test(j.url ?? '') ? `<a href="${esc(j.url)}">${esc(j.title)}</a>` : esc(j.title)}</div>
    <div style="color:#555">${esc(j.company || 'Company not stated')} &middot; ${esc(j.location)}${j.salary ? ' &middot; ' + esc(j.salary) : ''}${cvLink(j)}</div>
    <div style="margin-top:4px">${esc(j.reason)}</div>
    <div style="margin-top:4px;color:#2e7d32">✔ ${esc(j.matched_skills.join(', ') || '–')}</div>
    <div style="color:#c62828">✘ ${esc(j.missing_skills.join(', ') || '–')}</div>
  </td></tr>`;

const body = top.length
  ? `<table style="width:100%;border-collapse:collapse">${top.map(card).join('')}</table>`
  : `<p>No new jobs scored ${MIN_SCORE} or more today.</p>`;

const calls = name => { try { return $(name).all(); } catch (e) { return []; } };
const srcNote = [['Adzuna', 'Adzuna search'], ['Reed', 'Reed search']].map(([label, name]) => {
  const c = calls(name), failedCalls = c.filter(i => i.json.error).length;
  const n = jobs.filter(j => j.source === label.toLowerCase()).length;
  return `${label}: ${n} new${failedCalls ? ` (${failedCalls}/${c.length} requests failed)` : ''}`;
}).join(' · ');

const html = `<div style="font-family:Arial,sans-serif;max-width:640px">
  <h2 style="margin-bottom:4px">Job digest – ${esc(day)}</h2>
  <div style="color:#555">${jobs.length} new jobs · ${scored} scored${failed ? ` · ${failed} failed to score` : ''} · ${top.length} at ${MIN_SCORE}+</div>
  ${body}
  <p style="color:#888;font-size:12px">${esc(srcNote)}<br>Scoring tokens: ${inTok} in / ${outTok} out · est. $${costUsd.toFixed(4)}<br>Tailored CVs: ${cvOk.length} made${cvOlder ? ` (${cvOlder} for earlier jobs)` : ''}${cvFailed ? ` · ${cvFailed} failed (retried next run)` : ''} · ${cvIn} in / ${cvOut} out · est. $${cvCost.toFixed(4)}<br>Job briefs: ${briefOk} made${briefFailed ? ` · ${briefFailed} failed (retried next run)` : ''} · est. $${briefCost.toFixed(4)}<br>Total est. cost $${(costUsd + cvCost + briefCost).toFixed(4)} · full list in the Job Tracker sheet.</p>
</div>`;

const subject = top.length
  ? `Job digest: ${top.length} match${top.length > 1 ? 'es' : ''} (top ${top[0].score}) – ${day}`
  : `Job digest: no strong matches – ${day}`;

return [{ json: { subject, html, jobs_new: jobs.length, jobs_scored: scored, matches: top.length, input_tokens: inTok, output_tokens: outTok, cost_usd: costUsd, cvs_made: cvOk.length, cvs_failed: cvFailed, cv_cost_usd: cvCost } }];

// One Reed query per search term x location (local radius in miles + remote keyword).
const c = $('Search config').first().json;
const base = { resultsToTake: c.reed_results ?? 100 };
const items = [];
for (const term of c.reed_terms) {
  items.push({ json: { search_term: term, search_type: 'local',
    query: { ...base, keywords: term, locationName: c.local_area, distanceFromLocation: c.reed_distance_miles ?? 30 } } });
  items.push({ json: { search_term: term, search_type: 'remote',
    query: { ...base, keywords: `${term} remote` } } });
}
return items;

// Normalise Reed results into the shared job shape.
// Reed has no "posted since" filter, so drop listings older than reed_max_age_days here.
const clean = (s) => String(s ?? '')
  .replace(/<[^>]*>/g, ' ')
  .replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>')
  .replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&nbsp;/g, ' ')
  .replace(/&hellip;/g, '…').replace(/&ndash;/g, '–').replace(/&mdash;/g, '—').replace(/&pound;/g, '£')
  .replace(/&#(\d+);/g, (_, n) => String.fromCodePoint(Number(n)))
  .replace(/\s+/g, ' ')
  .trim();

const gbp = (n) => '£' + Math.round(n).toLocaleString('en-GB');
const formatSalary = (r) => {
  const { salary_min: min, salary_max: max } = r;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return String(r.salary_is_predicted) === '1' ? `${range} (est.)` : range;
};

const maxAge = $('Search config').first().json.reed_max_age_days ?? 2;
const cutoff = $now.setZone('Europe/London').minus({ days: maxAge }).toFormat('yyyy-MM-dd');
const isoDate = s => {
  const m = /^(\d{1,2})\/(\d{1,2})\/(\d{4})$/.exec(String(s ?? '').trim());
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : '';
};
const reedSalary = r => {
  const min = r.minimumSalary, max = r.maximumSalary;
  if (!min && !max) return '';
  const range = min && max && min !== max ? `${gbp(min)}–${gbp(max)}` : gbp(min || max);
  return (max || min) < 1000 ? `${range} (rate)` : range; // small numbers are day/hour rates
};

const must = $('Search config').first().json.title_must_contain ?? {};
const titleOk = (i, title) => {
  let term = '';
  try { term = $('Build Reed queries').itemMatching(i).json.search_term ?? ''; } catch (e) { return true; }
  const word = must[term.toLowerCase()];
  return !word || String(title ?? '').toLowerCase().includes(word);
};

const out = [];
for (const [i, item] of $input.all().entries()) {
  for (const r of item.json.results ?? []) {
    const posted = isoDate(r.date);
    if (posted && posted < cutoff) continue;
    const id = r.jobId ?? r.JobId;
    if (!id || !titleOk(i, r.jobTitle)) continue;
    out.push({ json: {
      job_id: `reed_${id}`,
      source: 'reed',
      title: clean(r.jobTitle),
      company: clean(r.employerName),
      location: clean(r.locationName),
      salary: reedSalary(r),
      url: r.jobUrl || `https://www.reed.co.uk/jobs/${id}`,
      description: clean(r.jobDescription),
      posted,
    }});
  }
}
return out;

// Check source health and add a cross-source de-dup key (Adzuna also lists Reed jobs).
// Fails the run (-> error alert) only if every request to every source failed.
const dedupKey = j => `${j.title ?? ''}|${j.company ?? ''}`
  .toLowerCase().replace(/[^a-z0-9|]+/g, ' ').replace(/\s+/g, ' ').trim();
const calls = name => { try { return $(name).all(); } catch (e) { return []; } };
const sources = { Adzuna: calls('Adzuna search'), Reed: calls('Reed search') };
const down = Object.entries(sources).filter(([, c]) => c.length && c.every(i => i.json.error));
if (down.length === Object.keys(sources).length) {
  const first = down[0][1][0].json.error;
  throw new Error('All job sources failed. First error: ' + (typeof first === 'string' ? first : first?.message ?? 'unknown'));
}
return $input.all()
  .filter(i => i.json.job_id)
  .map(i => ({ json: { ...i.json, dedup_key: dedupKey(i.json) } }));

// Jobs that may need a tailored CV: everything scored this run, plus older sheet rows with
// no CV yet. "Generate Tailored CV" applies the score threshold, age limit and cap.
const today = $now.setZone('Europe/London').toFormat('yyyy-MM-dd');
const fresh = $('Parse score').all().map(i => ({ ...i.json, date_found: today }));
const freshIds = new Set(fresh.map(j => j.job_id));
const older = $('Read existing jobs').all().map(i => i.json)
  .filter(r => r.job_id && !freshIds.has(r.job_id) && !String(r.cv_link ?? '').trim() && Number(r.score) >= 0 && r.score !== '');
return [...fresh, ...older].map(json => ({ json }));

// Sheet updates for the CV columns (matched on job_id).
return $('Generate CVs').all().map(i => i.json).filter(r => r.job_id)
  .map(r => ({ json: { job_id: r.job_id, cv_link: r.cv_link, cv_generated_at: r.cv_generated_at, tailoring_notes: r.tailoring_notes } }));

// Jobs with a CV and no job brief yet: CVs made this run, plus older sheet rows.
// "Generate Job Brief" applies the age limit and the cap.
const made = new Map($('Generate CVs').all().map(i => i.json).filter(r => r.job_id && r.cv_ok).map(r => [r.job_id, r.cv_link]));
const fresh = $('CV candidates').all().map(i => i.json).filter(j => made.has(j.job_id)).map(j => ({ ...j, cv_link: made.get(j.job_id) }));
const older = $('Read existing jobs').all().map(i => i.json)
  .filter(r => r.job_id && !made.has(r.job_id) && String(r.cv_link ?? '').trim() && !String(r.job_brief_link ?? '').trim());
return [...fresh, ...older].map(json => ({ json }));

// Sheet updates for the job_brief_link column (matched on job_id). Failures stay blank, so the next run retries.
return $('Generate briefs').all().map(i => i.json).filter(r => r.job_id && r.brief_ok)
